import itertools
import numpy as np
from scipy.optimize import differential_evolution

def solve_for_set(s):
    best_T = float('inf')
    # s is a tuple of 5 distinct positive numbers
    for subset in itertools.combinations(s, 4):
        # For a subset of 4, we want to minimize |e/h - g/f|
        # where e,f,g,h is a permutation of the subset.
        for p in itertools.permutations(subset):
            e, f, g, h = p
            T_val = abs(e/h - g/f)
            if T_val < best_T:
                best_T = T_val
    return best_T

def objective(r):
    r1, r2, r3, r4 = r
    x = [1, r1, r1*r2, r1*r2*r3, r1*r2*r3*r4]
    return -solve_for_set(tuple(x))

bounds = [(0.1, 10.0)] * 4
for _ in range(10):
    res = differential_evolution(objective, bounds, popsize=30, mutation=(0.5, 1), recombination=0.7)
    print(f"Result: {-res.fun}, Params: {res.x}")

